/* ============ 3x5 像素字体 ============ */
/* 每字符 5 行，每行 3 位（二进制） */
(function () {
  const F = {
    '0': [7,5,5,5,7], '1': [2,6,2,2,7], '2': [7,1,7,4,7], '3': [7,1,3,1,7],
    '4': [5,5,7,1,1], '5': [7,4,7,1,7], '6': [7,4,7,5,7], '7': [7,1,1,2,2],
    '8': [7,5,7,5,7], '9': [7,5,7,1,7],
    'A': [2,5,7,5,5], 'B': [6,5,6,5,6], 'C': [3,4,4,4,3], 'D': [6,5,5,5,6],
    'E': [7,4,6,4,7], 'F': [7,4,6,4,4], 'G': [3,4,5,5,3], 'H': [5,5,7,5,5],
    'I': [7,2,2,2,7], 'J': [1,1,1,5,2], 'K': [5,5,6,5,5], 'L': [4,4,4,4,7],
    'M': [5,7,7,5,5], 'N': [7,5,5,5,5], 'O': [7,5,5,5,7], 'P': [7,5,7,4,4],
    'Q': [7,5,5,7,1], 'R': [7,5,6,5,5], 'S': [3,4,2,1,6], 'T': [7,2,2,2,2],
    'U': [5,5,5,5,7], 'V': [5,5,5,5,2], 'W': [5,5,7,7,5], 'X': [5,5,2,5,5],
    'Y': [5,5,2,2,2], 'Z': [7,1,2,4,7],
    ':': [0,2,0,2,0], '.': [0,0,0,0,2], '-': [0,0,7,0,0], '/': [1,1,2,4,4],
    '+': [0,2,7,2,0], '!': [2,2,2,0,2], '?': [7,1,3,0,2], "'": [2,2,0,0,0],
    '(': [1,2,2,2,1], ')': [4,2,2,2,4], '<': [1,2,4,2,1], '>': [4,2,1,2,4],
    '=': [0,7,0,7,0], '%': [5,1,2,4,5], ',': [0,0,0,2,4], '*': [5,2,7,2,5],
    '#': [5,7,5,7,5], ' ': [0,0,0,0,0],
    '♥': [5,7,7,7,2], '★': [2,2,7,2,5], '▶': [6,6,6,6,6], '◆': [2,7,2,7,2],
    '↑': [2,7,2,2,2], '↓': [2,2,2,7,2], '←': [4,2,1,2,4], '→': [1,2,4,2,1],
  };

  /** 计算文本像素宽 */
  function textWidth(str, scale) {
    scale = scale || 1;
    return str.length * 4 * scale - scale; // 3px 字形 + 1px 间距
  }

  /** 在 ctx 上绘制像素文本（x,y 为左上角，单位=设计像素） */
  function drawText(ctx, str, x, y, scale, color, opts) {
    scale = scale || 1; opts = opts || {};
    if (opts.center) x -= textWidth(str, scale) / 2;
    if (opts.right) x -= textWidth(str, scale);
    str = String(str).toUpperCase();
    ctx.save();
    if (opts.glow) { ctx.shadowColor = color; ctx.shadowBlur = opts.glow; }
    ctx.fillStyle = color;
    for (let c = 0; c < str.length; c++) {
      const glyph = F[str[c]] || F['?'];
      const cx = x + c * 4 * scale;
      for (let r = 0; r < 5; r++) {
        const row = glyph[r];
        for (let b = 0; b < 3; b++) {
          if (row & (4 >> b)) ctx.fillRect(cx + b * scale, y + r * scale, scale, scale);
        }
      }
    }
    ctx.restore();
  }

  window.PixelFont = { drawText, textWidth };
})();
